import{z as t,x as n,o,c as i,q as d,j as c,D as a,d as l,s,S as B}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"阻塞与非阻塞赋值","description":"","frontmatter":{"title":"阻塞与非阻塞赋值","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/blocking-nonblocking.md","filePath":"cs/blocking-nonblocking.md","lastUpdated":1791063341000}'),r={name:"cs/blocking-nonblocking.md"};function A(p,e,m,h,g,_){const E=n("Mermaid");return o(),i("div",null,[e[2]||(e[2]=d('<h1 id="阻塞与非阻塞赋值" tabindex="-1">阻塞与非阻塞赋值 <a class="header-anchor" href="#阻塞与非阻塞赋值" aria-label="Permalink to &quot;阻塞与非阻塞赋值&quot;">​</a></h1><div class="epigraph"><p>同一 always 里，`=` 立刻改左值，`&lt;=` 采样右值、在时间步结束再更新；混用会让仿真看到的移位寄存器变成软件式覆盖。</p><footer>—— 据 Cummings, Nonblocking Assignments in Verilog Synthesis, Coding Styles That Kill, SNUG 2000；IEEE Std 1364；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/verilog-basics">上一课</a>钉了模块与 <code>always</code>，并把「仿真是否等于硬件」留作缺口。组成课的<a href="/cs/flipflop-types">触发器</a>是并行采样的。缺口是赋值运算符：<strong>阻塞 <code>=</code> 与非阻塞 <code>&lt;=</code></strong> 如何对应组合与边沿寄存器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>移位寄存器：三个 FF 应同时用旧值。若在 <code>posedge clk</code> 里写 <code>a=b; b=c;</code>，仿真变成串行覆盖，综合仍可能推出三只 FF——<strong>仿真/综合不一致</strong>。正确风格：时序块用 <code>&lt;=</code>，组合块用 <code>=</code>。缺口不是新的触发器电路，而是语言调度：NBA（nonblocking assignment）在当前活跃事件之后更新。</p><p>Cummings 的规则是工业常识：不要在同一 <code>always</code> 里对同一变量混用两种赋值。</p><p><span class="marginnote">术语翻译：阻塞 <code>=</code> 就是「这句不干完，下一句不许动」——左值立刻更新；非阻塞 <code>&lt;=</code> 是「先把右值抄下来，本时间步结束时统一更新」。区别不在电路，在仿真器的调度顺序：NBA 排在活跃事件之后的一个单独队列里。</span></p><h3 id="非阻塞不是「异步、不必等时钟」" tabindex="-1">非阻塞不是「异步、不必等时钟」 <a class="header-anchor" href="#非阻塞不是「异步、不必等时钟」" aria-label="Permalink to &quot;非阻塞不是「异步、不必等时钟」&quot;">​</a></h3><p><code>&lt;=</code> 仍然只在该 <code>always</code> 被触发时求值（通常是 <code>posedge</code>）。它不表示跨时钟域，也不表示组合旁路。把 nonblocking 理解成软件 async，CDC 课会对不齐。</p><p><span class="marginnote">Clifford Cummings, SNUG 2000 是本课主文献。IEEE 1364 规定事件队列。Harris 用移位寄存器当反例。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>always @(posedge clk)</code>：全部 <code>&lt;=</code>，读到的是本拍开始的寄存器值，对应并行 FF。<code>always @(*)</code>：<code>=</code> 描述组合函数，避免意外锁存（每个输出在所有分支赋值）。临时组合量在时序块里可用阻塞算出中间值再 NBA 给寄存器——要极克制，本课推荐中间量拉到组合块。</p>',12)),(o(),c(B,null,{default:a(()=>[s(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20POSEDGE%5B%22posedge%20always%22%5D%20--%3E%20NBA%5B%22%E9%9D%9E%E9%98%BB%E5%A1%9E%EF%BC%9A%E5%B9%B6%E8%A1%8C%20FF%22%5D%0A%20%20COMB%5B%22%E7%BB%84%E5%90%88%20always%22%5D%20--%3E%20BA%5B%22%E9%98%BB%E5%A1%9E%EF%BC%9A%E8%BF%9E%E7%BA%BF%E9%80%BB%E8%BE%91%22%5D%0A%20%20MIX%5B%22%E6%B7%B7%E7%94%A8%E5%90%8C%E4%B8%80%E5%8F%98%E9%87%8F%22%5D%20--%3E%20X%5B%22%E4%BB%BF%E7%9C%9F%E7%BB%BC%E5%90%88%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%0A%20%20NBA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%BB%BC%E5%90%88%E6%88%90%E7%BD%91%E8%A1%A8%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<p><span class="marginnote">数字实例：想在时钟沿交换两个寄存器，写 <code>a&lt;=b; b&lt;=a;</code> 则每拍真的互换。若误写成阻塞 <code>a=b; b=a;</code>，两句在拍内串行执行，<code>b</code> 拿到的是已经变成旧 <code>b</code> 的 <code>a</code>——两个寄存器都成了旧 <code>b</code>，交换悄悄失败，仿真和硬件同时错。</span></p><p><code>#delay</code> 只为仿真，综合忽略。后课网表不再有这两种赋值，只剩门延迟。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>综合器把 NBA 到 <code>reg</code> 映射为触发器，把组合 <code>=</code> 映射为门。错误风格可能推断出锁存（level-sensitive），与边沿规格不符，<a href="/cs/setup-hold">建立保持</a>窗口会换一套。本课把风格钉死，让后课 STA 分析的是预期的 FF+组合。</p><p>一个时钟拍内两种赋值的时间线，值得单独画。</p>',5)),(o(),c(B,null,{default:a(()=>[s(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20CLK%5B%22%E6%97%B6%E9%92%9F%E6%B2%BF%E8%A7%A6%E5%8F%91%22%5D%20--%3E%20ACT%5B%22%E6%B4%BB%E8%B7%83%E5%8C%BA%EF%BC%9A%E9%98%BB%E5%A1%9E%E8%B5%8B%E5%80%BC%E7%AB%8B%E5%8D%B3%E6%94%B9%E5%B7%A6%E5%80%BC%22%5D%0A%20%20ACT%20--%3E%20NBAQ%5B%22NBA%20%E5%8C%BA%EF%BC%9A%E5%8F%B3%E5%80%BC%E5%B7%B2%E9%87%87%E6%A0%B7%EF%BC%8C%E6%9A%82%E4%B8%8D%E6%9B%B4%E6%96%B0%22%5D%0A%20%20NBAQ%20--%3E%20STEP%5B%22%E6%97%B6%E9%97%B4%E6%AD%A5%E7%BB%93%E6%9D%9F%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%E7%BB%9F%E4%B8%80%E6%9B%B4%E6%96%B0%22%5D%0A%20%20STEP%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E6%8B%8D%E8%AF%BB%E5%88%B0%E7%9A%84%E6%98%AF%E6%96%B0%E5%80%BC%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">直觉类比：非阻塞像全班考试——人人先把题目抄到草稿上（采样右值），下课铃一响同时誊到正式答卷（更新寄存器）；阻塞则是传纸条改答案，改一个传一个，顺序错一步全盘错。硬件要的是「同一拍并行采样」，所以时序块永远用 <code>&lt;=</code>。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 SystemVerilog 的 <code>always_ff</code>/<code>always_comb</code> 全部语义差异（它们有助于工具检查，推荐用，但不替代对 NBA 的理解）。不引入 PLI。不把 Python 协程类比过来。</p><p>后课默认：时序非阻塞、组合阻塞；移位与流水线按并行采样理解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>&lt;=</code> 对应并行触发器采样；<code>=</code> 对应组合立刻传播。</li><li>混用制造仿真/综合裂缝。</li><li>下一课：这些块如何变成门级网表。</li><li>出处：Cummings, SNUG 2000；IEEE 1364；Harris and Harris。</li></ul>',6))])}const u=t(r,[["render",A]]);export{b as __pageData,u as default};
